const items = $input.all();
const results = [];

for (const item of items) {
  const mimeType = item.json.mimeType || '';
  const fileName = item.json.name || '';

  let shouldExtract = false;
  let extractType = null;

  // PDF
  if (mimeType === 'application/pdf') {
    shouldExtract = true;
    extractType = 'pdf';
  }
  // Word
  else if (mimeType.includes('wordprocessingml') || mimeType === 'application/msword' || mimeType === 'application/vnd.google-apps.document') {
    shouldExtract = true;
    extractType = 'docx';
  }
  // Excel et CSV
  else if (mimeType.includes('spreadsheetml') || mimeType.includes('ms-excel') || mimeType === 'application/vnd.google-apps.spreadsheet') {
    shouldExtract = true;
    extractType = 'xlsx';
  }
  // PowerPoint
  else if (mimeType.includes('presentationml') || mimeType.includes('ms-powerpoint') || mimeType === 'application/vnd.google-apps.presentation') {
    shouldExtract = true;
    extractType = 'pptx';
  }
  // Texte brut, CSV, Markdown (pas besoin d'extraction)
  else if (mimeType.includes('text/') || mimeType === 'text/csv' || mimeType === 'text/plain' || mimeType === 'text/markdown') {
    shouldExtract = false;
    extractType = 'text';
  }
  // Par défaut, on considère comme texte
  else {
    console.warn(`Type MIME inconnu pour ${fileName}: ${mimeType} - traité comme texte`);
    shouldExtract = false;
    extractType = 'text';
  }

  results.push({
    json: {
      ...item.json,
      shouldExtract,
      extractType
    },
    binary: item.binary
  });

  console.log(`${fileName}: ${mimeType} -> ${shouldExtract ? 'Extract ' + extractType : 'Texte direct'}`);
}

return results;

const items = $input.all();

return items.map(item => {
  let textContent = '';

  try {
    // Essayer de lire depuis le binaire
    if (item.binary?.data?.data) {
      const buffer = Buffer.from(item.binary.data.data, 'base64');
      textContent = buffer.toString('utf-8');
    }
    // Sinon essayer depuis binary.data directement
    else if (item.binary?.data) {
      textContent = item.binary.data.toString('utf-8');
    }

    // Si toujours vide, mettre un message
    if (!textContent || textContent.trim() === '') {
      textContent = `[Fichier vide: ${item.json.name}]`;
      console.log(`⚠️ Fichier vide détecté: ${item.json.name}`);
    } else {
      console.log(`✅ Texte lu: ${item.json.name} (${textContent.length} caractères)`);
    }
  } catch (error) {
    console.error(`❌ Erreur lecture ${item.json.name}:`, error.message);
    textContent = `[Erreur de lecture: ${error.message}]`;
  }

  return {
    json: {
      ...item.json,
      data: textContent
    }
  };
});

const items = $input.all();

return items.map(item => {
  return {
    json: {
      pageContent: item.json.data || '',
      metadata: {
        fileId: item.json.id,
        fileName: item.json.name,
        mimeType: item.json.mimeType,
        webViewLink: item.json.webViewLink,
        modifiedTime: item.json.modifiedTime,
        indexedAt: new Date().toISOString(),
        source: 'google_drive'
      }
    }
  };
});

const items = $input.all();
return [{
  json: {
    success: true,
    message: 'Indexation terminée',
    documentsIndexed: items.length,
    timestamp: new Date().toISOString()
  }
}];

const items = $input.all();

items.forEach(item => {
  console.log('Fichier à télécharger:', {
    name: item.json.name,
    id: item.json.id,
    mimeType: item.json.mimeType
  });
});

return items;

const items = $input.all();
const forceReindex = $('Fusionner Entrées').first().json?.forceReindex || false;

const filesToCheck = items.map(item => ({
  ...item,
  json: {
    ...item.json,
    needsIndexing: false
  }
}));

if (forceReindex) {
  console.log('Force reindex activé - traitement de tous les fichiers');
  return filesToCheck.map(item => ({
    ...item,
    json: { ...item.json, needsIndexing: true }
  }));
}

const oneDayAgo = new Date();
oneDayAgo.setDate(oneDayAgo.getDate() - 1);

const recentlyModified = filesToCheck.map(item => {
  const modifiedTime = new Date(item.json.modifiedTime);
  const isRecent = modifiedTime > oneDayAgo;

  if (isRecent) {
    console.log(`Fichier potentiellement à indexer: ${item.json.name} (modifié le ${modifiedTime.toISOString()})`);
  }

  return {
    ...item,
    json: {
      ...item.json,
      needsIndexing: isRecent
    }
  };
});

return recentlyModified;

const items = $input.all();

const filtered = items.filter(item => {
  const needsIndexing = item.json.needsIndexing;

  if (!needsIndexing) {
    return false;
  }

  const qdrantPoints = item.json.qdrantResult?.result?.points || [];
  const existsInQdrant = qdrantPoints.length > 0;

  if (!existsInQdrant) {
    console.log(`✅ Nouveau fichier à indexer: ${item.json.name}`);
    return true;
  }

  const qdrantModifiedTime = qdrantPoints[0]?.payload?.metadata?.modifiedTime;
  const currentModifiedTime = item.json.modifiedTime;

  if (qdrantModifiedTime && currentModifiedTime > qdrantModifiedTime) {
    console.log(`♻️ Fichier mis à jour à ré-indexer: ${item.json.name}`);
    return true;
  }

  console.log(`⏭️ Fichier déjà à jour dans Qdrant: ${item.json.name}`);
  return false;
});

if (filtered.length === 0) {
  console.log('Aucun fichier à indexer');
  return [{ json: { noFiles: true, message: 'Aucun fichier à indexer' }}];
}

console.log(`${filtered.length} fichier(s) à indexer`);
return filtered;

const items = $input.all();
const results = [];

const qdrantUrl = 'https://qdrant.connectika.fr';
const apiKey = '2f36208b5ec5f75da66834c37a679cb38dca7d20536613aded61ecdbeea9d3f0';

for (const item of items) {
  try {
    const body = {
      filter: {
        must: [
          {
            key: 'metadata.fileId',
            match: {
              value: item.json.id
            }
          }
        ]
      },
      limit: 1
    };

    const response = await fetch(`${qdrantUrl}/collections/RAG/points/scroll`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...(apiKey ? { 'api-key': apiKey } : {})
      },
      body: JSON.stringify(body)
    });

    const qdrantResult = await response.json();

    results.push({
      json: {
        ...item.json,
        qdrantResult: qdrantResult
      }
    });

    console.log(`Vérifié: ${item.json.name} - Existe: ${qdrantResult.result?.points?.length > 0}`);
  } catch (error) {
    console.error(`Erreur pour ${item.json.name}:`, error.message);
    results.push({
      json: {
        ...item.json,
        qdrantResult: { result: { points: [] } }
      }
    });
  }
}

return results;

